// metrics.forecast: Forecast when a queue or the cluster backlog drains
// Generated by `pnpm nx g @app/generators:action metrics.forecast`, then edited. Run
// `pnpm nx run contracts:api-docs` so the committed API documents follow.
//
// The drain ETA of a queue's depth (or of the cluster's) from the hot window, by an adaptive-window
// regression trusted only at R2 0.95 and over (MON-05). Every state is explicit: `ok` carries a 95 %
// band, and a series no straight line explains is `no-reliable-forecast`, never an ETA (I-13).
import { z } from 'zod';

import { ConnectionIdSchema } from '../brands.ts';
import { defineAction } from '../kit/define-action.ts';
import {
  ForecastSchema,
  MetricsStatusSchema,
  QueueRefSchema,
  METRIC_IDS,
} from './metrics-types.ts';

const count = z.number().int().nonnegative();

export const MetricsForecastTargetSchema = z.discriminatedUnion('scope', [
  z.strictObject({ scope: z.literal('cluster') }),
  z.strictObject({
    scope: z.literal('queue'),
    vhost: QueueRefSchema.shape.vhost,
    name: QueueRefSchema.shape.name,
  }),
]);

export const MetricsForecastInputSchema = z.strictObject({
  cid: ConnectionIdSchema,
  target: MetricsForecastTargetSchema,
  /** Only the last this-many milliseconds of the hot window are used. Default: all of it. */
  windowMs: count.optional(),
});

export const MetricsForecastOutputSchema = z.strictObject({
  target: MetricsForecastTargetSchema,
  /** The series the forecast was made from: the depth of the queue, or the cluster's messages. */
  metric: z.enum(METRIC_IDS),
  forecast: ForecastSchema,
  /** Points of that series in the window, and the time of the newest. */
  points: count,
  asOf: count.optional(),
  status: MetricsStatusSchema,
});

export const metricsForecast = defineAction({
  id: 'metrics.forecast',
  kind: 'query',
  summary: 'Forecast when a queue or the cluster backlog drains',
  input: MetricsForecastInputSchema,
  output: MetricsForecastOutputSchema,
  permission: 'broker.read',
  risk: 'none',
  planning: 'none',
  audit: 'none',
  target: (input) => ({ connectionId: input.cid }),
  http: { method: 'POST', path: '/connections/{cid}/metrics/forecasts' },
  since: '1.0',
});
